def fill_brand_slugs(apps, schema_editor):
    from django.utils.text import slugify

    Brand = apps.get_model("catalog", "Brand")
    taken = set()
    for brand in Brand.objects.order_by("id"):
        base = slugify(brand.name, allow_unicode=True)[:60] or "brand"
        slug, n = base, 2
        while slug in taken:
            slug, n = f"{base}-{n}", n + 1
        taken.add(slug)
        Brand.objects.filter(pk=brand.pk).update(slug=slug)


